window.QUIZ_DATA = {"chapter": 4, "title": "Chapter 4 — Operational Procedures", "sections": [{"id": "4.1", "title": "Documentation and Support Systems", "file": "4.1 Documentation and Support Systems Information Management.html", "count": 20}, {"id": "4.2", "title": "Change Management Best Practices", "file": "4.2 Change Management Best Practices.html", "count": 15}, {"id": "4.3", "title": "Backup and Recovery Best Practices", "file": "4.3 Backup and Recovery Best Practices.html", "count": 10}, {"id": "4.4", "title": "Safety and Environmental Controls", "file": "4.4 Safety and Environmental Controls.html", "count": 11}, {"id": "4.5", "title": "MSDS, Disposal, and Power Protection", "file": "4.5 MSDS, Disposal, and Power Protection.html", "count": 9}, {"id": "4.6", "title": "Incident Response, Licensing, and Compliance", "file": "4.6 Incident Response, Licensing, and Compliance.html", "count": 18}, {"id": "4.7", "title": "Professionalism and Customer Service", "file": "4.7 Professionalism and Customer Service.html", "count": 16}, {"id": "4.8", "title": "Scripting Basics and Use Cases", "file": "4.8 Scripting Basics and Use Cases.html", "count": 16}, {"id": "4.9", "title": "Remote Access Tools and Security", "file": "4.9 Remote Access Tools and Security.html", "count": 15}, {"id": "4.10", "title": "AI Tools, Policy, and Limitations", "file": "4.10 AI Tools, Policy, and Limitations.html", "count": 8}], "terms": [{"id": "4.1-0", "section": "4.1", "sectionTitle": "Documentation and Support Systems", "category": "Ticketing systems", "name": "Ticketing systems", "definition": "A centralized platform (e.g., ServiceNow, Jira Service Management, Zendesk) used to create, assign, track, and close support incidents and service requests. Tickets provide an audit trail, prevent issues from being lost, and enable reporting on response times and recurring problems.", "scenario": "Every incident lives in ServiceNow so nothing is lost and you can report response times. What platform type is that?"}, {"id": "4.1-1", "section": "4.1", "sectionTitle": "Documentation and Support Systems", "category": "Ticketing systems", "name": "User information", "definition": "Identify who is affected and how to reach them. Standard fields include name, employee ID, department, location, phone number, email, and manager.", "scenario": "The ticket needs the employee’s name, ID, department, phone, and manager before you start. What field set is that?"}, {"id": "4.1-2", "section": "4.1", "sectionTitle": "Documentation and Support Systems", "category": "Ticketing systems", "name": "Device information", "definition": "Record the hardware or system involved: hostname, asset tag, serial number, model, OS version, IP address, and physical location.", "scenario": "You log hostname, asset tag, serial, OS version, and IP so the next tech can find the machine. What field set is that?"}, {"id": "4.1-3", "section": "4.1", "sectionTitle": "Documentation and Support Systems", "category": "Ticketing systems", "name": "Description of issues", "definition": "The initial report of what the user is experiencing — symptoms, error messages, when it started, and what changed recently.", "scenario": "The user wrote the symptoms, the error text, when it started, and what changed yesterday. What ticket field is that?"}, {"id": "4.1-4", "section": "4.1", "sectionTitle": "Documentation and Support Systems", "category": "Ticketing systems", "name": "Categories", "definition": "Classify tickets by type so they route to the correct team and appear in meaningful reports. Examples: hardware, software, network, access/permissions, email, printing, mobile, security.", "scenario": "You tag the ticket hardware vs software vs network so it routes to the right queue and reports make sense. What are those tags called?"}, {"id": "4.1-5", "section": "4.1", "sectionTitle": "Documentation and Support Systems", "category": "Ticketing systems", "name": "Severity", "definition": "Indicates business impact and urgency — how badly operations are affected and how quickly a response is required.", "scenario": "Payroll is down company-wide, so this is treated as high business impact and needs a fast response. What rating is that?"}, {"id": "4.1-6", "section": "4.1", "sectionTitle": "Documentation and Support Systems", "category": "Ticketing systems", "name": "Escalation levels", "definition": "Define when and how a ticket moves to a higher tier of support — Tier 1 (help desk) → Tier 2 (specialists) → Tier 3 (engineers/vendors).", "scenario": "Tier 1 is stuck, so the ticket moves to specialists, then engineers/vendors. What process is that?"}, {"id": "4.1-7", "section": "4.1", "sectionTitle": "Documentation and Support Systems", "category": "Ticketing systems", "name": "Clear, concise written communication", "definition": "Ticket notes should be professional, factual, and readable by anyone who picks up the ticket later. Avoid jargon the user may not understand in customer-facing replies; use precise technical terms in internal notes.", "scenario": "Customer replies stay plain-language; internal notes use exact technical terms so the next tech can pick it up. What writing standard is that?"}, {"id": "4.1-8", "section": "4.1", "sectionTitle": "Documentation and Support Systems", "category": "Asset management", "name": "Inventory lists", "definition": "A complete record of organizational assets — desktops, laptops, monitors, printers, mobile devices, servers, and peripherals. Lists typically include make, model, serial number, location, status (in use, spare, retired), and purchase date.", "scenario": "A spreadsheet of every laptop, printer, and spare with make, serial, location, and status. What asset record is that?"}, {"id": "4.1-9", "section": "4.1", "sectionTitle": "Documentation and Support Systems", "category": "Asset management", "name": "Configuration management database (CMDB)", "definition": "A structured repository that stores configuration items (CIs) and their relationships — not just what you own, but how components connect. A laptop CI might link to its installed OS, software licenses, network segment, and assigned user.", "scenario": "The laptop CI is linked to its OS, licenses, VLAN, and assigned user — not just a list of stuff you own. What database is that?"}, {"id": "4.1-10", "section": "4.1", "sectionTitle": "Documentation and Support Systems", "category": "Asset management", "name": "Asset tags and IDs", "definition": "Unique identifiers (barcode labels, QR codes, or RFID tags) physically affixed to equipment and mirrored in inventory systems.", "scenario": "A barcode sticker on the chassis matches the ID in the inventory system. What identifier is that?"}, {"id": "4.1-11", "section": "4.1", "sectionTitle": "Documentation and Support Systems", "category": "Asset management", "name": "Procurement life cycle", "definition": "The end-to-end process of acquiring IT assets: identify need → request approval → purchase → receive and tag → deploy → maintain → retire/dispose.", "scenario": "Need → approve → buy → receive/tag → deploy → maintain → retire. What asset process is that?"}, {"id": "4.1-12", "section": "4.1", "sectionTitle": "Documentation and Support Systems", "category": "Asset management", "name": "Warranty and licensing", "definition": "Warranty — Manufacturer coverage for repair or replacement; track start/end dates and support contract numbers.", "scenario": "You track the manufacturer coverage dates and support contract number so a dead laptop still gets replaced. What records are those?"}, {"id": "4.1-13", "section": "4.1", "sectionTitle": "Documentation and Support Systems", "category": "Asset management", "name": "Assigned users", "definition": "Record which employee, department, or shared resource currently has custody of each asset. Critical for accountability, off-boarding (reclaiming equipment), and locating devices during incidents.", "scenario": "The laptop is checked out to Jordan in Finance; you need that name to reclaim it at off-boarding. What field is that?"}, {"id": "4.1-14", "section": "4.1", "sectionTitle": "Documentation and Support Systems", "category": "Types of documents", "name": "Incident reports", "definition": "Formal documentation of a security or operational incident: what happened, when, systems affected, actions taken, root cause, and lessons learned.", "scenario": "After a breach you write what happened, systems hit, actions taken, root cause, and lessons learned. What document is that?"}, {"id": "4.1-15", "section": "4.1", "sectionTitle": "Documentation and Support Systems", "category": "Types of documents", "name": "Standard operating procedures (SOPs)", "definition": "Step-by-step instructions for recurring IT tasks so any qualified technician performs them the same way every time.", "scenario": "Any qualified tech should image a kiosk the same way every time using the same numbered steps. What document is that?"}, {"id": "4.1-16", "section": "4.1", "sectionTitle": "Documentation and Support Systems", "category": "Types of documents", "name": "New user / onboarding setup checklist", "definition": "A ordered list of provisioning tasks for new hires: create AD/Entra account, assign groups, configure email, deploy hardware, install required software, set up MFA, grant building access, and schedule orientation.", "scenario": "New hire: AD account, groups, email, laptop, MFA, badge, orientation — all on one ordered list. What document is that?"}, {"id": "4.1-17", "section": "4.1", "sectionTitle": "Documentation and Support Systems", "category": "Types of documents", "name": "User off-boarding checklist", "definition": "Security-focused teardown when an employee leaves: disable accounts, revoke licenses, collect hardware, forward email, remove from groups, wipe mobile devices, rotate shared passwords they knew, and archive data per policy.", "scenario": "Someone quit: disable accounts, pull the laptop, wipe the phone, rotate shared passwords, archive mail. What document is that?"}, {"id": "4.1-18", "section": "4.1", "sectionTitle": "Documentation and Support Systems", "category": "Types of documents", "name": "Service-level agreements (SLAs)", "definition": "Formal commitments defining expected service quality — response time, resolution time, uptime percentage, and support hours.", "scenario": "The vendor contract promises a 1-hour response and 99.9% uptime during support hours. What agreement is that?"}, {"id": "4.1-19", "section": "4.1", "sectionTitle": "Documentation and Support Systems", "category": "Types of documents", "name": "Knowledge base / articles", "definition": "A searchable library of solutions, how-to guides, and FAQs — often linked directly from the ticketing system. Reduces repeat tickets by enabling users and Tier 1 staff to self-resolve common issues.", "scenario": "Tier 1 searches a library of how-tos linked from the ticket tool so users can self-fix password resets. What resource is that?"}, {"id": "4.2-0", "section": "4.2", "sectionTitle": "Change Management Best Practices", "category": "Documented business processes", "name": "Rollback plan", "definition": "A defined set of procedures to return a system to its original configuration if an update fails.", "scenario": "If the patch fails, you already wrote the steps to put the system back the way it was. What plan is that?"}, {"id": "4.2-1", "section": "4.2", "sectionTitle": "Change Management Best Practices", "category": "Documented business processes", "name": "Backup plan", "definition": "Alternate steps (Plan B, Plan C, etc.) to execute if issues arise during implementation — such as using local installation files on a flash drive if internet downloads fail.", "scenario": "If the CDN is down during the window, Plan B is to install from a USB with the files already on it. What plan is that?"}, {"id": "4.2-2", "section": "4.2", "sectionTitle": "Change Management Best Practices", "category": "Documented business processes", "name": "Sandbox testing", "definition": "Executing and verifying changes in an isolated, self-contained test environment to validate stability and test rollback procedures without risking production uptime.", "scenario": "You try the change in an isolated lab first so production never takes the hit. What testing is that?"}, {"id": "4.2-3", "section": "4.2", "sectionTitle": "Change Management Best Practices", "category": "Documented business processes", "name": "Responsible staff members", "definition": "Clear division of responsibilities across:", "scenario": "The requestor, implementer, and approver are named so nobody is guessing who does what. What staffing item is that?"}, {"id": "4.2-4", "section": "4.2", "sectionTitle": "Change Management Best Practices", "category": "Change management procedures", "name": "Request forms", "definition": "Standardized digital forms that capture necessary details — including risk evaluations, scope, purpose, and rollback plans — for submission, tracking, and auditing.", "scenario": "A digital form captures risk, scope, purpose, and how you would undo it before anyone touches production. What artifact is that?"}, {"id": "4.2-5", "section": "4.2", "sectionTitle": "Change Management Best Practices", "category": "Change management procedures", "name": "Purpose of the change", "definition": "Clear business justification for the modification, such as:", "scenario": "The ticket explains the business reason — close a CVE, not “because we felt like it.” What field is that?"}, {"id": "4.2-6", "section": "4.2", "sectionTitle": "Change Management Best Practices", "category": "Change management procedures", "name": "Scope of the change", "definition": "Defining the boundary of the update to determine whether it affects a tiny group of users or the core infrastructure of the entire organization.", "scenario": "You state whether this hits three users or the core infrastructure for the whole company. What field is that?"}, {"id": "4.2-7", "section": "4.2", "sectionTitle": "Change Management Best Practices", "category": "Change management procedures", "name": "Change type", "definition": "Low-risk, routine, and pre-approved modifications (e.g., replacing a user’s broken monitor) that do not require formal board review.", "scenario": "Swapping a user’s broken monitor is low-risk, routine, and already pre-approved — no board meeting. What classification is that?"}, {"id": "4.2-8", "section": "4.2", "sectionTitle": "Change Management Best Practices", "category": "Change management procedures", "name": "Date and time of change", "definition": "Designated, pre-approved time slots (e.g., off-peak hours such as Sundays at 2 a.m.) set aside for system changes when user impact is minimized.", "scenario": "The window is Sunday 2 a.m. so users are not in the middle of the workday. What scheduling item is that?"}, {"id": "4.2-9", "section": "4.2", "sectionTitle": "Change Management Best Practices", "category": "Change management procedures", "name": "Affected systems / impact", "definition": "Identification of all hardware, applications, and services impacted by the update.", "scenario": "You list every app, server, and service that will go dark if this change misfires. What analysis is that?"}, {"id": "4.2-10", "section": "4.2", "sectionTitle": "Change Management Best Practices", "category": "Change management procedures", "name": "Risk analysis and risk level", "definition": "Evaluating the technical risk of executing the change — e.g., unbootable operating systems, non-functional patches, or data loss.", "scenario": "You score the chance of an unbootable OS, a bad patch, or data loss before anyone clicks Go. What analysis is that?"}, {"id": "4.2-11", "section": "4.2", "sectionTitle": "Change Management Best Practices", "category": "Change management procedures", "name": "Change board approvals", "definition": "Review and authorization by a CCB representing multiple departments to evaluate risks, prioritize changes, and prevent scheduling conflicts.", "scenario": "A cross-department CCB reviews risk, priority, and calendar collisions before the change is allowed. What approval is that?"}, {"id": "4.2-12", "section": "4.2", "sectionTitle": "Change Management Best Practices", "category": "Change management procedures", "name": "Implementation", "definition": "Carrying out the approved change according to the defined steps and schedule during the approved maintenance window.", "scenario": "During the approved window you actually run the documented steps. What phase is that?"}, {"id": "4.2-13", "section": "4.2", "sectionTitle": "Change Management Best Practices", "category": "Change management procedures", "name": "Peer review", "definition": "Reviewing implementation, rollback, and backup plans with experienced IT peers and subject matter experts before execution.", "scenario": "Another senior tech reads the implement/undo/Plan B docs before you touch production. What review is that?"}, {"id": "4.2-14", "section": "4.2", "sectionTitle": "Change Management Best Practices", "category": "Change management procedures", "name": "End-user acceptance", "definition": "The final phase where end users test the updated software or system to confirm that it functions properly and meets business needs.", "scenario": "After the change, the people who use the app confirm it still does their job. What sign-off is that?"}, {"id": "4.3-0", "section": "4.3", "sectionTitle": "Backup and Recovery Best Practices", "category": "Backup types", "name": "Full backup", "definition": "Backs up all system data — including the OS, applications, and user files — in a single set.", "scenario": "One job copies the OS, apps, and user files in a single complete set. What backup type is that?"}, {"id": "4.3-1", "section": "4.3", "sectionTitle": "Backup and Recovery Best Practices", "category": "Backup types", "name": "Incremental backup", "definition": "Backs up only files created or modified since the last backup — whether that last backup was full or incremental.", "scenario": "Tonight’s job copies only files new or changed since last night’s job — full or otherwise. What backup type is that?"}, {"id": "4.3-2", "section": "4.3", "sectionTitle": "Backup and Recovery Best Practices", "category": "Backup types", "name": "Differential backup", "definition": "Backs up all data that has changed since the last full backup.", "scenario": "Each night copies everything changed since Sunday’s complete set, not since last night. What backup type is that?"}, {"id": "4.3-3", "section": "4.3", "sectionTitle": "Backup and Recovery Best Practices", "category": "Backup types", "name": "Synthetic full backup", "definition": "Creates a new full backup synthetically by consolidating existing full and incremental/differential backup sets locally — rather than pulling a fresh full backup over the network.", "scenario": "The server builds a new complete set locally by merging last week’s complete set with later jobs, so you do not pull another full copy over the WAN. What backup type is that?"}, {"id": "4.3-4", "section": "4.3", "sectionTitle": "Backup and Recovery Best Practices", "category": "Recovery methods", "name": "In-place / overwrite restore", "definition": "Restores data directly to its original location, replacing and overwriting any existing files currently on the system.", "scenario": "Restore writes files back onto the original path and replaces whatever is there now. What restore method is that?"}, {"id": "4.3-5", "section": "4.3", "sectionTitle": "Backup and Recovery Best Practices", "category": "Recovery methods", "name": "Alternative location restore", "definition": "Restores files to a separate designated path or device rather than overwriting existing data.", "scenario": "You restore into a side folder so you can compare without wiping the live files. What restore method is that?"}, {"id": "4.3-6", "section": "4.3", "sectionTitle": "Backup and Recovery Best Practices", "category": "Recovery methods", "name": "Frequency and testing", "definition": "Regular recovery testing and audits should be conducted to simulate file or system restoration — verifying data integrity and identifying potential restoration failures before an actual system outage occurs.", "scenario": "Once a quarter you actually restore a file in a drill so you find broken tapes before a real outage. What practice is that?"}, {"id": "4.3-7", "section": "4.3", "sectionTitle": "Backup and Recovery Best Practices", "category": "Backup rotation and location", "name": "Onsite vs. offsite", "definition": "Local backups provide high bandwidth, rapid recovery times, and no extra maintenance fees — but remain vulnerable to localized physical disasters (fire, flood, theft).", "scenario": "A copy in the server room is fast to restore but a fire takes it too; a copy in another city survives that fire. What location choice is that?"}, {"id": "4.3-8", "section": "4.3", "sectionTitle": "Backup and Recovery Best Practices", "category": "Backup rotation and location", "name": "Grandfather-Father-Son (GFS)", "definition": "A structured rotation strategy that layers backups over distinct time intervals:", "scenario": "Daily, weekly, and monthly media rotate so you can go back a day, a week, or a month. What rotation scheme is that?"}, {"id": "4.3-9", "section": "4.3", "sectionTitle": "Backup and Recovery Best Practices", "category": "Backup rotation and location", "name": "3-2-1 backup rule", "definition": "A foundational backup framework requiring:", "scenario": "Keep three copies, on two kinds of media, with one copy somewhere else. What backup rule is that?"}, {"id": "4.4-0", "section": "4.4", "sectionTitle": "Safety and Environmental Controls", "category": "ESD prevention and component handling", "name": "ESD straps", "definition": "Wristband devices that equalize electrical potential between the technician and the chassis, featuring breakaway snaps for mobility.", "scenario": "A wristband with a breakaway snap ties your potential to the chassis while you work inside a PC. What is that?"}, {"id": "4.4-1", "section": "4.4", "sectionTitle": "Safety and Environmental Controls", "category": "ESD prevention and component handling", "name": "ESD mats and pads", "definition": "Conductive surface mats or desk pads used to safely balance static potential when working on components or standing near equipment.", "scenario": "You stand or work on a conductive pad so static can bleed off before it hits a board. What is that?"}, {"id": "4.4-2", "section": "4.4", "sectionTitle": "Safety and Environmental Controls", "category": "ESD prevention and component handling", "name": "Antistatic bags", "definition": "Specially designed metallic or static-shielding bags that protect isolated computer parts from static discharges during transport or storage.", "scenario": "A spare RAM stick rides in a metallic shielding pouch until you seat it. What packaging is that?"}, {"id": "4.4-3", "section": "4.4", "sectionTitle": "Safety and Environmental Controls", "category": "ESD prevention and component handling", "name": "Proper component handling and storage", "definition": "Always handle circuit boards by their outer edges rather than exposed circuits or chips.", "scenario": "You pick up the motherboard by the edges, not by the chips or gold contacts. What handling rule is that?"}, {"id": "4.4-4", "section": "4.4", "sectionTitle": "Safety and Environmental Controls", "category": "Electrical and workspace safety", "name": "Disconnect power", "definition": "Unplug power cords from computers, printers, or peripheral devices before opening cases to prevent electrical shock.", "scenario": "Before the case comes off, the power cord comes out of the wall and the PSU. What safety step is that?"}, {"id": "4.4-5", "section": "4.4", "sectionTitle": "Safety and Environmental Controls", "category": "Electrical and workspace safety", "name": "High-voltage components and grounding", "definition": "Never open or service power supplies, CRT displays, or laser printers — internal capacitors can retain dangerous residual voltage even when unplugged.", "scenario": "You do not open a PSU, CRT, or laser printer — capacitors can still bite when unplugged. What hazard area is that?"}, {"id": "4.4-6", "section": "4.4", "sectionTitle": "Safety and Environmental Controls", "category": "Electrical and workspace safety", "name": "Cable management", "definition": "Keep walkways clear by bundling cables using Velcro or cable ties, and taping or covering any cables crossing floor paths to eliminate trip hazards.", "scenario": "Power bricks and Ethernet are bundled and covered where they cross the aisle so nobody trips. What practice is that?"}, {"id": "4.4-7", "section": "4.4", "sectionTitle": "Safety and Environmental Controls", "category": "Personal safety and environmental compliance", "name": "Personal protective equipment (PPE)", "definition": "Select PPE matched to the specific hazard — toner, battery acid, and metal shavings each require different protection.", "scenario": "Toner cleanup gets a mask; battery acid gets gloves and goggles matched to that hazard. What gear category is that?"}, {"id": "4.4-8", "section": "4.4", "sectionTitle": "Safety and Environmental Controls", "category": "Personal safety and environmental compliance", "name": "Lifting techniques", "definition": "Lift heavy computers or equipment using leg strength rather than bending the back — keep the load close, feet shoulder-width apart, and avoid twisting while carrying.", "scenario": "A tower is heavy: feet apart, load close, lift with legs, no twist. What technique is that?"}, {"id": "4.4-9", "section": "4.4", "sectionTitle": "Safety and Environmental Controls", "category": "Personal safety and environmental compliance", "name": "Fire safety", "definition": "Unplug burning equipment immediately if safe to do so.", "scenario": "A PSU is smoking. If you can reach it safely, you pull the plug first. What topic is that?"}, {"id": "4.4-10", "section": "4.4", "sectionTitle": "Safety and Environmental Controls", "category": "Personal safety and environmental compliance", "name": "Compliance with government regulations", "definition": "Adhere to local building codes for electrical and fire safety, and observe environmental regulations regarding proper disposal and recycling of hazardous e-waste — such as old batteries, CRTs, and computers.", "scenario": "Building electrical/fire codes plus rules for recycling batteries and CRTs, not the dumpster. What obligation is that?"}, {"id": "4.5-0", "section": "4.5", "sectionTitle": "MSDS, Disposal, and Power Protection", "category": "MSDS and asset disposal", "name": "MSDS / SDS documentation", "definition": "Required by OSHA, SDS documents contain product composition, health hazard information, first aid guidelines, firefighting measures, and safe disposal steps for hazardous materials like batteries and toner.", "scenario": "OSHA paperwork lists composition, first aid, firefighting, and disposal for toner and batteries. What document is that?"}, {"id": "4.5-1", "section": "4.5", "sectionTitle": "MSDS, Disposal, and Power Protection", "category": "MSDS and asset disposal", "name": "Proper battery disposal", "definition": "Batteries from mobile devices, laptops, and Uninterruptible Power Supplies (UPS) contain hazardous materials and must never be thrown into regular trash.", "scenario": "A swollen laptop cell and a dead UPS pack cannot go in the office trash. What disposal rule is that?"}, {"id": "4.5-2", "section": "4.5", "sectionTitle": "MSDS, Disposal, and Power Protection", "category": "MSDS and asset disposal", "name": "Proper toner disposal", "definition": "Toner cartridges should be:", "scenario": "Empty printer cartridges go back to the vendor or a recycler, not the bin. What disposal rule is that?"}, {"id": "4.5-3", "section": "4.5", "sectionTitle": "MSDS, Disposal, and Power Protection", "category": "MSDS and asset disposal", "name": "Proper disposal of devices", "definition": "Electronic devices and components containing hazardous elements must be taken to authorized local hazardous material or e-waste recycling locations.", "scenario": "Old PCs and boards with hazardous parts go to an authorized e-waste site. What disposal rule is that?"}, {"id": "4.5-4", "section": "4.5", "sectionTitle": "MSDS, Disposal, and Power Protection", "category": "Climate control, ventilation, and maintenance", "name": "Temperature and humidity awareness", "definition": "Operating equipment creates significant internal heat from CPUs and memory, requiring active cooling to ensure optimal operation.", "scenario": "The closet is too hot and too dry; CPUs need cooling and humidity in a safe band. What environmental check is that?"}, {"id": "4.5-5", "section": "4.5", "sectionTitle": "MSDS, Disposal, and Power Protection", "category": "Climate control, ventilation, and maintenance", "name": "Location, equipment placement, and ventilation", "definition": "Workspaces require adequate ventilation when cleaning dusty computers or handling paper-heavy printer environments.", "scenario": "You move the dusty tower out of a closed office and keep printers where air can move. What placement issue is that?"}, {"id": "4.5-6", "section": "4.5", "sectionTitle": "MSDS, Disposal, and Power Protection", "category": "Climate control, ventilation, and maintenance", "name": "Dust cleanup — compressed air and vacuums", "definition": "Use a vacuum (preferably one designed for electronics) when cleaning out system dust indoors If using compressed air to blow out heavy dust, move the computer outside the building — blowing dust indoors redistributes contaminants and creates inhalation hazards", "scenario": "Indoors you vacuum electronics dust; compressed air happens outside so you do not blow it into lungs. What cleanup method is that?"}, {"id": "4.5-7", "section": "4.5", "sectionTitle": "MSDS, Disposal, and Power Protection", "category": "Power management and protection", "name": "Uninterruptible Power Supply (UPS)", "definition": "Provides backup power during outages and guards against brownouts (under-voltage) and power surges.", "scenario": "A battery box keeps the server up through a blink and also covers brownouts and surges. What device is that?"}, {"id": "4.5-8", "section": "4.5", "sectionTitle": "MSDS, Disposal, and Power Protection", "category": "Power management and protection", "name": "Surge suppressor", "definition": "Absorbs excessive voltage spikes on electrical lines and redirects them safely to the ground.", "scenario": "A strip that only clamps voltage spikes to ground — no battery runtime. What device is that?"}, {"id": "4.6-0", "section": "4.6", "sectionTitle": "Incident Response, Licensing, and Compliance", "category": "Incident response", "name": "Chain of custody", "definition": "Maintains evidence integrity by documenting every person who contacts, accesses, or modifies physical or digital evidence.", "scenario": "Every person who touched the seized laptop is logged so evidence stays defensible. What record is that?"}, {"id": "4.6-1", "section": "4.6", "sectionTitle": "Incident Response, Licensing, and Compliance", "category": "Incident response", "name": "Informing management and law enforcement", "definition": "Initial incident responders gather logs, monitoring metrics, and user accounts to verify a breach, then immediately notify designated internal leadership and law enforcement authorities as required by organizational policy and applicable law.", "scenario": "Logs confirm a breach; policy says tell leadership and the police next, not the whole company Slack. What step is that?"}, {"id": "4.6-2", "section": "4.6", "sectionTitle": "Incident Response, Licensing, and Compliance", "category": "Incident response", "name": "Copy of drive — data integrity and preservation", "definition": "Requires a bit-for-bit (byte-for-byte) clone of the storage drive — ideally using a hardware write blocker — to capture unallocated space and deleted files without altering the original evidence.", "scenario": "You take a bit-for-bit clone through a write blocker so deleted space is kept and the original is not altered. What copy is that?"}, {"id": "4.6-3", "section": "4.6", "sectionTitle": "Incident Response, Licensing, and Compliance", "category": "Incident response", "name": "Incident documentation", "definition": "Formally records an executive summary, acquisition steps, analytical findings, and definitive conclusions to establish internal clarity and support legal proceedings.", "scenario": "The write-up has an executive summary, how you acquired evidence, findings, and conclusions for court. What record is that?"}, {"id": "4.6-4", "section": "4.6", "sectionTitle": "Incident Response, Licensing, and Compliance", "category": "Incident response", "name": "Order of volatility", "definition": "Data must be captured starting with the most volatile components that disappear quickly when power is lost or systems are rebooted. Follow this general sequence:", "scenario": "Capture RAM and live network state before you pull the plug; disk and backups wait. What capture order is that?"}, {"id": "4.6-5", "section": "4.6", "sectionTitle": "Incident Response, Licensing, and Compliance", "category": "Licensing, DRM, and EULAs", "name": "Valid licenses", "definition": "Software usage must conform to specific licensing models, including:", "scenario": "Installs must match the purchased model — seats, cores, or subscription — not a cracked key. What requirement is that?"}, {"id": "4.6-6", "section": "4.6", "sectionTitle": "Incident Response, Licensing, and Compliance", "category": "Licensing, DRM, and EULAs", "name": "Perpetual license agreement", "definition": "Grants lifetime access to a software version for a single upfront cost, common in personal-use software. Updates beyond the purchased version may require a separate purchase or maintenance agreement.", "scenario": "One upfront fee, that version is yours for life; newer major versions may cost extra. What license type is that?"}, {"id": "4.6-7", "section": "4.6", "sectionTitle": "Incident Response, Licensing, and Compliance", "category": "Licensing, DRM, and EULAs", "name": "Personal-use vs. corporate-use license", "definition": "Covers individual or limited household devices — not valid for business deployment.", "scenario": "Home-and-hobby terms are not valid on the office fleet; the business needs a corporate entitlement. What license distinction is that?"}, {"id": "4.6-8", "section": "4.6", "sectionTitle": "Incident Response, Licensing, and Compliance", "category": "Licensing, DRM, and EULAs", "name": "Open-source license", "definition": "Free and Open-Source Software (FOSS) provides full access to the source code for customization and compilation. Closed-source commercial software provides compiled executables only — source code is proprietary.", "scenario": "You can read and rebuild the source; a commercial EXE would only ship compiled. What license type is that?"}, {"id": "4.6-9", "section": "4.6", "sectionTitle": "Incident Response, Licensing, and Compliance", "category": "Non-Disclosure Agreements", "name": "NDA / MNDA", "definition": "Legal contracts establishing confidentiality to protect sensitive commercial information and trade secrets.", "scenario": "Vendors and staff sign a contract not to leak trade secrets they see on the engagement. What agreement is that?"}, {"id": "4.6-10", "section": "4.6", "sectionTitle": "Incident Response, Licensing, and Compliance", "category": "Regulated data", "name": "Credit card payment information", "definition": "Governs cardholder data with requirements for network isolation, cardholder data protection, access controls, and ongoing auditing.", "scenario": "Cardholder numbers need isolation, access control, and audits — PCI-style handling. What data type is that?"}, {"id": "4.6-11", "section": "4.6", "sectionTitle": "Incident Response, Licensing, and Compliance", "category": "Regulated data", "name": "Personal government-issued information", "definition": "Standardized government identifiers — such as Social Security Numbers or driver's license details — subject to statutory restrictions to prevent identity theft and privacy breaches.", "scenario": "SSNs and driver’s license numbers on a share are statutory identity data, not just “HR files.” What data type is that?"}, {"id": "4.6-12", "section": "4.6", "sectionTitle": "Incident Response, Licensing, and Compliance", "category": "Regulated data", "name": "PII — Personally Identifiable Information", "definition": "Any standalone or combined data point capable of identifying an individual, requiring strict handling policies to prevent unauthorized access or account takeover.", "scenario": "Name plus birthday plus address together can identify a person, so handling policy is strict. What data type is that?"}, {"id": "4.6-13", "section": "4.6", "sectionTitle": "Incident Response, Licensing, and Compliance", "category": "Regulated data", "name": "Healthcare data / PHI", "definition": "Covers patient medical histories, clinical records, and treatment plans. HIPAA mandates administrative, physical, and technical safeguards for any system storing or transmitting PHI.", "scenario": "Clinic notes and treatment plans sit under HIPAA safeguards. What data type is that?"}, {"id": "4.6-14", "section": "4.6", "sectionTitle": "Incident Response, Licensing, and Compliance", "category": "Regulated data", "name": "Data retention requirements", "definition": "Mandatory storage schedules driven by operational needs — such as versioning or malware recovery — or statutory compliance obligations applying to financial, legal, or government records.", "scenario": "Finance says keep those mailboxes seven years for statute, even if ops only needed 90 days. What requirement is that?"}, {"id": "4.6-15", "section": "4.6", "sectionTitle": "Incident Response, Licensing, and Compliance", "category": "Policies and compliance", "name": "Acceptable Use Policy (AUP)", "definition": "An employee agreement specifying allowed and prohibited uses of organizational IT assets — internet access, hardware, and mobile devices — to limit corporate legal liability.", "scenario": "The employee handbook says no torrenting on the work laptop and no personal file shares. What policy is that?"}, {"id": "4.6-16", "section": "4.6", "sectionTitle": "Incident Response, Licensing, and Compliance", "category": "Policies and compliance", "name": "Regulatory and business compliance requirements", "definition": "Organizational standards designed to satisfy legal mandates and industry guidelines — spanning data protection, financial reporting, healthcare privacy, and sector-specific regulations.", "scenario": "Internal rules exist so the company can pass HIPAA, SOX, or industry audits. What requirement set is that?"}, {"id": "4.6-17", "section": "4.6", "sectionTitle": "Incident Response, Licensing, and Compliance", "category": "Policies and compliance", "name": "Splash screens", "definition": "Pre-login banner prompts that display operational expectations, legal disclaimers, or liability warnings requiring user consent before access is granted.", "scenario": "Before the login box, a banner with legal terms must be accepted. What UI control is that?"}, {"id": "4.7-0", "section": "4.7", "sectionTitle": "Professionalism and Customer Service", "category": "Appearance and professional demeanor", "name": "Appropriate attire", "definition": "Match the organizational dress code, whether adhering to formal standards (e.g., slacks and ties) or business casual environments, to foster a comfortable and professional workplace.", "scenario": "The site is business casual, so you match slacks-and-polo instead of a concert tee. What standard is that?"}, {"id": "4.7-1", "section": "4.7", "sectionTitle": "Professionalism and Customer Service", "category": "Appearance and professional demeanor", "name": "Professional communication", "definition": "Translate complex technology issues into clear, accessible concepts using non-technical language. Avoid slang, tech jargon, and acronyms when working with users or decision-makers.", "scenario": "You explain the outage in plain language with no acronym soup for the CFO. What skill is that?"}, {"id": "4.7-2", "section": "4.7", "sectionTitle": "Professionalism and Customer Service", "category": "Appearance and professional demeanor", "name": "Positive attitude and confidence", "definition": "Maintain an approachable, equal-partner approach during interactions to reassure users — especially during critical data loss or complex technical failures.", "scenario": "The user’s files look gone; you stay calm and treat them as a partner, not a problem. What demeanor is that?"}, {"id": "4.7-3", "section": "4.7", "sectionTitle": "Professionalism and Customer Service", "category": "Appearance and professional demeanor", "name": "Cultural sensitivity and titles", "definition": "Respect designated professional titles and credentials — such as addressing a PhD holder as \"Doctor\" — and follow organizational guidelines for respectful treatment of all colleagues and customers.", "scenario": "The ticket is for Dr. Patel — you use the title they asked for. What sensitivity is that?"}, {"id": "4.7-4", "section": "4.7", "sectionTitle": "Professionalism and Customer Service", "category": "Appearance and professional demeanor", "name": "Punctuality", "definition": "Arrive on time for scheduled commitments — on-site appointments, meetings, and remote support sessions. If you will be late, notify the customer or team as early as possible.", "scenario": "The on-site slot is 2:00. You will be 20 minutes late, so you call before 2:00. What habit is that?"}, {"id": "4.7-5", "section": "4.7", "sectionTitle": "Professionalism and Customer Service", "category": "Appearance and professional demeanor", "name": "Avoiding distractions", "definition": "Eliminate personal interruptions such as personal calls, texting, or browsing social media during work hours.", "scenario": "At the desk you pocket the phone and skip social media until the visit is done. What habit is that?"}, {"id": "4.7-6", "section": "4.7", "sectionTitle": "Professionalism and Customer Service", "category": "Handling difficult situations and customer interactivity", "name": "Active listening", "definition": "Allow customers to fully describe their issue without interrupting, avoiding premature assumptions about the root cause.", "scenario": "You let the user finish the whole story before you guess it is the printer driver. What skill is that?"}, {"id": "4.7-7", "section": "4.7", "sectionTitle": "Professionalism and Customer Service", "category": "Handling difficult situations and customer interactivity", "name": "Conflict avoidance", "definition": "Refrain from arguing with or acting defensively toward customers when emotions run high. Partner with the user toward a solution rather than contradicting them.", "scenario": "The user is angry and wrong about the cause; you do not argue — you work the fix together. What approach is that?"}, {"id": "4.7-8", "section": "4.7", "sectionTitle": "Professionalism and Customer Service", "category": "Handling difficult situations and customer interactivity", "name": "Non-judgmental teaching", "definition": "Act as a teacher rather than judging a customer's level of technical knowledge, helping them feel more confident with their technology.", "scenario": "They have never used a trackpad. You teach the click, you do not mock the skill gap. What approach is that?"}, {"id": "4.7-9", "section": "4.7", "sectionTitle": "Professionalism and Customer Service", "category": "Handling difficult situations and customer interactivity", "name": "Clarifying and verifying", "definition": "Ask probing open-ended questions, take detailed notes, and restate or repeat the issue back to the customer to verify understanding and refine the scope of the problem.", "scenario": "You ask open questions, write notes, and repeat the problem back so they can correct you. What technique is that?"}, {"id": "4.7-10", "section": "4.7", "sectionTitle": "Professionalism and Customer Service", "category": "Handling difficult situations and customer interactivity", "name": "Discretion", "definition": "Keep internal business matters, customer experiences, and workplace encounters confidential. Never post work details on public forums or social media.", "scenario": "You never post a funny user story from the ticket on public social media. What obligation is that?"}, {"id": "4.7-11", "section": "4.7", "sectionTitle": "Professionalism and Customer Service", "category": "Expectation management and service delivery", "name": "Setting timelines and status updates", "definition": "Provide regular status communications for long-term tickets — such as setting calendar reminders to contact the user weekly during manufacturer part delays.", "scenario": "The part is a week out; you put a reminder to email the user each Monday with status. What practice is that?"}, {"id": "4.7-12", "section": "4.7", "sectionTitle": "Professionalism and Customer Service", "category": "Expectation management and service delivery", "name": "Repair vs. replacement options", "definition": "Present clear repair or replacement options, outlining the advantages and disadvantages of each so the user can make informed decisions.", "scenario": "You lay out fix-the-board vs buy-a-new-laptop with cost and downtime so they can choose. What conversation is that?"}, {"id": "4.7-13", "section": "4.7", "sectionTitle": "Professionalism and Customer Service", "category": "Expectation management and service delivery", "name": "Proper documentation", "definition": "Document technical discussions and service details thoroughly — for example, following up phone calls with detailed summary emails that recap the issue, steps taken, and next actions.", "scenario": "After the call you email a recap of the issue, what you did, and the next step. What work product is that?"}, {"id": "4.7-14", "section": "4.7", "sectionTitle": "Professionalism and Customer Service", "category": "Expectation management and service delivery", "name": "Follow-up", "definition": "Check in with the user after closing a ticket to verify complete satisfaction and catch minor residual issues before they escalate.", "scenario": "The ticket is closed; tomorrow you ping them to confirm it still works. What practice is that?"}, {"id": "4.7-15", "section": "4.7", "sectionTitle": "Professionalism and Customer Service", "category": "Privacy and confidentiality", "name": "Handling sensitive materials", "definition": "Protect all private, confidential, or sensitive personal data visible on computers, printouts, or desktops. IT professionals hold elevated access permissions and must maintain absolute confidentiality and trust regarding enterprise and personal data.", "scenario": "Pay stubs are on the desk and payroll is on screen; you look away and do not discuss it. What handling rule is that?"}, {"id": "4.8-0", "section": "4.8", "sectionTitle": "Scripting Basics and Use Cases", "category": "Script file types", "name": ".bat — Windows Batch file", "definition": "Executed at the command line, dating back to DOS and OS/2. Uses simple sequential commands (echo, copy, del, net use) and is still widely used for basic Windows automation tasks.", "scenario": "A DOS-era file of echo/copy/del/net use lines still maps a drive at logon. What script type is that?"}, {"id": "4.8-1", "section": "4.8", "sectionTitle": "Scripting Basics and Use Cases", "category": "Script file types", "name": ".ps1 — PowerShell script", "definition": "Used primarily by Windows system administrators, leveraging built-in functions called cmdlets to access and modify operating system parameters and Active Directory.", "scenario": "An admin uses cmdlets to change AD and Windows settings in one file. What script type is that?"}, {"id": "4.8-2", "section": "4.8", "sectionTitle": "Scripting Basics and Use Cases", "category": "Script file types", "name": ".vbs — Visual Basic Script", "definition": "Used for desktop scripting, backend web server operations, and Microsoft Office macros. Runs through the Windows Script Host (wscript.exe or cscript.exe).", "scenario": "Office macros and WScript/CScript run this older Microsoft desktop language. What script type is that?"}, {"id": "4.8-3", "section": "4.8", "sectionTitle": "Scripting Basics and Use Cases", "category": "Script file types", "name": ".sh — Unix/Linux shell script", "definition": "Identified by a shebang or hashbang (#!) on its initial line, which specifies the interpreter — for example #!/bin/bash or #!/bin/sh.", "scenario": "The first line is #!/bin/bash so Linux knows which interpreter to use. What script type is that?"}, {"id": "4.8-4", "section": "4.8", "sectionTitle": "Scripting Basics and Use Cases", "category": "Script file types", "name": ".js — JavaScript", "definition": "Used to enable dynamic interactivity within web browsers — distinct from the Java programming language despite the similar name.", "scenario": "The web page animates and validates a form in the browser — not the Java language. What language is that?"}, {"id": "4.8-5", "section": "4.8", "sectionTitle": "Scripting Basics and Use Cases", "category": "Script file types", "name": ".py — Python script", "definition": "Provides cross-platform compatibility across Windows, macOS, Linux, and cloud-based automation. Popular for IT automation, data collection, and infrastructure-as-code tooling.", "scenario": "The same automation file runs on Windows, macOS, Linux, and in the cloud. What script type is that?"}, {"id": "4.8-6", "section": "4.8", "sectionTitle": "Scripting Basics and Use Cases", "category": "Use cases for scripting", "name": "Basic automation", "definition": "Handles repetitive or mundane tasks at high execution speeds without requiring manual input or direct oversight — freeing technicians for complex troubleshooting.", "scenario": "A nightly job does the boring clicks at machine speed so techs can troubleshoot instead. What use case is that?"}, {"id": "4.8-7", "section": "4.8", "sectionTitle": "Scripting Basics and Use Cases", "category": "Use cases for scripting", "name": "Restarting machines", "definition": "Triggers remote system reboots following application updates or security patches, or schedules periodic reboots to clear hardware memory leaks.", "scenario": "After patch Tuesday a job remotely reboots the lab so the updates actually apply. What use case is that?"}, {"id": "4.8-8", "section": "4.8", "sectionTitle": "Scripting Basics and Use Cases", "category": "Use cases for scripting", "name": "Remapping network drives", "definition": "Automatically maps shared network drives during user login, repository updates, or backup processes — ensuring consistent drive letters across the organization.", "scenario": "At logon a script always reconnects S: to the same share so letters stay consistent. What use case is that?"}, {"id": "4.8-9", "section": "4.8", "sectionTitle": "Scripting Basics and Use Cases", "category": "Use cases for scripting", "name": "Installation of applications", "definition": "Automates software deployments by mapping installation drives, running setup routines with pre-filled prompts, and initiating post-install reboots — standard in enterprise imaging and SCCM/Intune deployments.", "scenario": "Imaging/Intune silently runs setup with answers and a reboot — no clicking Next. What use case is that?"}, {"id": "4.8-10", "section": "4.8", "sectionTitle": "Scripting Basics and Use Cases", "category": "Use cases for scripting", "name": "Automated backups", "definition": "Executes resource-intensive data transfers to backup drives during off-peak hours, minimizing impact on user productivity and network bandwidth.", "scenario": "A 2 a.m. job copies file servers to backup disks when nobody is on the WAN. What use case is that?"}, {"id": "4.8-11", "section": "4.8", "sectionTitle": "Scripting Basics and Use Cases", "category": "Use cases for scripting", "name": "Gathering of information and data", "definition": "Automates system monitoring, hardware and software inventory collection, and vulnerability scanning using protocols like SNMP.", "scenario": "A scheduled job walks SNMP and dumps hardware/software inventory plus vuln hits. What use case is that?"}, {"id": "4.8-12", "section": "4.8", "sectionTitle": "Scripting Basics and Use Cases", "category": "Use cases for scripting", "name": "Initiating updates", "definition": "Deploys operating system patches, application upgrades, and updated hardware device drivers without user intervention — critical for maintaining security posture at scale.", "scenario": "OS patches, app upgrades, and drivers push to the fleet with no user click. What use case is that?"}, {"id": "4.8-13", "section": "4.8", "sectionTitle": "Scripting Basics and Use Cases", "category": "Other considerations when using scripts", "name": "Unintentionally introducing malware", "definition": "Running unverified installation scripts or deploying infected software files can inadvertently distribute malware across networked endpoints.", "scenario": "Someone ran an unsigned installer script from a forum and malware hit every mapped PC. What scripting risk is that?"}, {"id": "4.8-14", "section": "4.8", "sectionTitle": "Scripting Basics and Use Cases", "category": "Other considerations when using scripts", "name": "Inadvertently changing system settings", "definition": "Unintended registry modifications or configuration edits can break system resources, requiring thorough pre-deployment testing and rollback scripts.", "scenario": "A one-line registry edit in the script broke printers; you needed a rollback script. What scripting risk is that?"}, {"id": "4.8-15", "section": "4.8", "sectionTitle": "Scripting Basics and Use Cases", "category": "Other considerations when using scripts", "name": "Browser or system crashes due to mishandling of resources", "definition": "Syntax errors, loose characters, or logical bugs within scripts can cause resource exhaustion, service outages, or system downtime.", "scenario": "A loop in the script pegged RAM until the browser and the box died. What scripting risk is that?"}, {"id": "4.9-0", "section": "4.9", "sectionTitle": "Remote Access Tools and Security", "category": "Remote access methods, tools, and use cases", "name": "RDP — Remote Desktop Protocol", "definition": "Proprietary Microsoft protocol providing remote GUI access to desktops and servers across operating systems. Delivers a full interactive desktop session over the network.", "scenario": "You get a full Windows desktop session over Microsoft’s GUI protocol. What method is that?"}, {"id": "4.9-1", "section": "4.9", "sectionTitle": "Remote Access Tools and Security", "category": "Remote access methods, tools, and use cases", "name": "VPN — Virtual Private Network", "definition": "Encrypts traffic between a remote client and a network VPN concentrator across public networks like the internet.", "scenario": "The laptop encrypts all traffic to the office concentrator across the public internet. What method is that?"}, {"id": "4.9-2", "section": "4.9", "sectionTitle": "Remote Access Tools and Security", "category": "Remote access methods, tools, and use cases", "name": "VNC — Virtual Network Computing", "definition": "Open-source remote desktop solution operating via the Remote Frame Buffer (RFB) protocol across multi-platform environments — Windows, macOS, and Linux.", "scenario": "An open RFB remote-desktop client works the same on Windows, Mac, and Linux. What method is that?"}, {"id": "4.9-3", "section": "4.9", "sectionTitle": "Remote Access Tools and Security", "category": "Remote access methods, tools, and use cases", "name": "SSH — Secure Shell", "definition": "Terminal-based command-line interface providing encrypted communications to execute remote configuration changes. Replaces unencrypted Telnet.", "scenario": "You need an encrypted command line on a Linux box instead of Telnet. What method is that?"}, {"id": "4.9-4", "section": "4.9", "sectionTitle": "Remote Access Tools and Security", "category": "Remote access methods, tools, and use cases", "name": "RMM — Remote Monitoring and Management", "definition": "Centralized MSP software suite used to monitor, patch, inventory, and manage client networks and endpoints from a single console.", "scenario": "The MSP console patches, inventories, and watches every client endpoint from one pane. What suite is that?"}, {"id": "4.9-5", "section": "4.9", "sectionTitle": "Remote Access Tools and Security", "category": "Remote access methods, tools, and use cases", "name": "SPICE — Simple Protocol for Independent Computing Environments", "definition": "Lightweight, high-efficiency protocol engineered for seamless graphics rendering, clipboard sharing, and remote access to virtual machines — commonly used with KVM/QEMU virtualization.", "scenario": "KVM/QEMU VMs get a light protocol for graphics, clipboard, and console. What protocol is that?"}, {"id": "4.9-6", "section": "4.9", "sectionTitle": "Remote Access Tools and Security", "category": "Remote access methods, tools, and use cases", "name": "WinRM — Windows Remote Management", "definition": "Enables administrators to remotely execute scripts and commands on target Windows systems and receive output without establishing an interactive desktop or terminal session.", "scenario": "You fire a command on a remote Windows host and get stdout back with no desktop session. What feature is that?"}, {"id": "4.9-7", "section": "4.9", "sectionTitle": "Remote Access Tools and Security", "category": "Remote access methods, tools, and use cases", "name": "Third-party tools", "definition": "Specialized external utilities classified by operational purpose:", "scenario": "TeamViewer/AnyDesk-class apps sit outside the OS’s built-in remote stack. What category is that?"}, {"id": "4.9-8", "section": "4.9", "sectionTitle": "Remote Access Tools and Security", "category": "Security considerations", "name": "RDP security", "definition": "Listens on default TCP port 3389. Requires multi-factor authentication (MFA) to prevent brute-force attacks and unauthorized system takeovers.", "scenario": "TCP 3389 is exposed; you require MFA so password sprays cannot take the desktop. What hardening is that?"}, {"id": "4.9-9", "section": "4.9", "sectionTitle": "Remote Access Tools and Security", "category": "Security considerations", "name": "VPN security", "definition": "Requires multi-factor authentication alongside primary credentials to prevent unauthorized network entry via stolen login details.", "scenario": "Stolen VPN passwords are not enough — the concentrator also demands a second factor. What hardening is that?"}, {"id": "4.9-10", "section": "4.9", "sectionTitle": "Remote Access Tools and Security", "category": "Security considerations", "name": "VNC security", "definition": "Vulnerable to brute-force credential attacks if relying solely on basic username/password setups. Requires additional authentication factors and should be tunneled through SSH or VPN when possible.", "scenario": "Plain username/password on RFB is brute-force bait; tunnel it through SSH or a VPN and add another factor. What hardening is that?"}, {"id": "4.9-11", "section": "4.9", "sectionTitle": "Remote Access Tools and Security", "category": "Security considerations", "name": "SSH security", "definition": "Listens on TCP port 22. Enhances security by utilizing:", "scenario": "TCP 22 should use keys (and MFA) rather than a reusable password. What hardening is that?"}, {"id": "4.9-12", "section": "4.9", "sectionTitle": "Remote Access Tools and Security", "category": "Security considerations", "name": "RMM security", "definition": "Highly targeted by attackers due to multi-tenant access across multiple customer environments — compromising one RMM console can affect every managed client.", "scenario": "One compromised MSP console would reach every tenant you manage, so that console is a high-value target. What risk area is that?"}, {"id": "4.9-13", "section": "4.9", "sectionTitle": "Remote Access Tools and Security", "category": "Security considerations", "name": "WinRM security", "definition": "Requires administrative credential authentication to verify and trust scripts before execution on the remote system. Use HTTPS (port 5986) rather than unencrypted HTTP (port 5985) in production.", "scenario": "Remote Windows commands should ride HTTPS 5986 with admin creds, not clear HTTP 5985. What hardening is that?"}, {"id": "4.9-14", "section": "4.9", "sectionTitle": "Remote Access Tools and Security", "category": "Security considerations", "name": "Third-party tool security", "definition": "Require multi-factor authentication, robust permission controls, and restricted user access to mitigate data leaks and unauthorized remote control.", "scenario": "The vendor remote tool needs MFA, tight roles, and a short allow-list so a leaked seat cannot drive every PC. What hardening is that?"}, {"id": "4.10-0", "section": "4.10", "sectionTitle": "AI Tools, Policy, and Limitations", "category": "Application integration", "name": "AI in everyday tools", "definition": "Everyday tools routinely feature integrated AI, including:", "scenario": "Mail, docs, and the help desk already have copilots baked into everyday apps. What trend is that?"}, {"id": "4.10-1", "section": "4.10", "sectionTitle": "AI Tools, Policy, and Limitations", "category": "Policy", "name": "Appropriate use", "definition": "Legitimate AI applications in IT and enterprise environments include:", "scenario": "Policy allows summarizing a public KB article or drafting a ticket reply with no secrets pasted in. What use is that?"}, {"id": "4.10-2", "section": "4.10", "sectionTitle": "AI Tools, Policy, and Limitations", "category": "Policy", "name": "Improper use and plagiarism", "definition": "Inappropriate applications include:", "scenario": "A tech pastes customer PHI into a chatbot and turns in the answer as their own work. What misuse is that?"}, {"id": "4.10-3", "section": "4.10", "sectionTitle": "AI Tools, Policy, and Limitations", "category": "Limitations", "name": "Bias", "definition": "Occurs when training data sets are incomplete or unrepresentative, causing the model to yield unfair or skewed outcomes.", "scenario": "The model ranks résumés unfairly because the training set was mostly one demographic. What limitation is that?"}, {"id": "4.10-4", "section": "4.10", "sectionTitle": "AI Tools, Policy, and Limitations", "category": "Limitations", "name": "Hallucinations", "definition": "Instances where AI confidently presents false information — such as misidentifying images or providing incorrect historical facts during product announcements.", "scenario": "The chatbot invents a command and a citation that never existed, said with full confidence. What limitation is that?"}, {"id": "4.10-5", "section": "4.10", "sectionTitle": "AI Tools, Policy, and Limitations", "category": "Limitations", "name": "Accuracy", "definition": "Current models frequently produce inaccurate predictions or incorrect factual statements during evaluation tests, demonstrating that AI tools remain far from error-free.", "scenario": "On a fact-check, the model is often just wrong — you still have to verify. What limitation is that?"}, {"id": "4.10-6", "section": "4.10", "sectionTitle": "AI Tools, Policy, and Limitations", "category": "Private vs. public AI", "name": "Public AI", "definition": "Internet-accessible tools (e.g., ChatGPT, Google Gemini) trained on vast internet-wide data sources. They offer broad informational access but pose data privacy and security risks if sensitive details or personal profiles are ingested.", "scenario": "ChatGPT-class tools on the open internet are handy but must not ingest payroll files. What AI class is that?"}, {"id": "4.10-7", "section": "4.10", "sectionTitle": "AI Tools, Policy, and Limitations", "category": "Private vs. public AI", "name": "Private AI", "definition": "Enterprise-controlled environments operated internally. They restrict access to proprietary organizational data, enhancing data security and protecting internal secrets from external exposure.", "scenario": "The company hosts its own model on internal data so trade secrets never leave the tenant. What AI class is that?"}], "total": 138};
